    "title": "Claude 这下尴尬了。今天 A 社披露了三起 AI 攻击安全事故，直追 OpenAI，并且，这些攻击早已经发生了。\\n\\n今天 A 社回查了 141,006 次可能接触互联网的网络安全评测，发现三款 Claude 模型未经授权进入了三家真实机构的生产系统。这可不是当下发生的事，最早的事故出现在 4 月份，无声无息，真是让人类嗷嚎了。入侵你，但你毫无感觉。\\n\\n前几天 OpenAI 模型攻入 Hugging Face 的事件引发了轩然大波，Anthropic 启动了大规模的模型测试回溯，从几个月前的日",
